begin read only;
set local statement_timeout='5s';
select clock_timestamp() observed_at,
 (select jsonb_build_object('enabled',enabled,'reservation_cap_enforced',reservation_cap_enforced,'ceiling_microusd',ceiling_microusd,'reserved_microusd',reserved_microusd,'price_valid_until',price_valid_until) from private.ai_test_budget_v5 where singleton) budget,
 (select jsonb_build_object('reservation_count',count(*),'unfinished_count',count(*) filter(where settled_microusd is null),'unfinished_hold_microusd',coalesce(sum(max_cost_microusd) filter(where settled_microusd is null),0),'settled_microusd',coalesce(sum(settled_microusd),0),'ledger_exposure_microusd',sum(coalesce(settled_microusd,max_cost_microusd))) from private.ai_test_reservations_v5) ledger,
 (select jsonb_build_object('count',count(*),'latest',max(recorded_at)) from private.ai_test_usage_v5) usage,
 (select jsonb_agg(jsonb_build_object('routine',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'prosecdef',p.prosecdef,'proconfig',p.proconfig,'acl',p.proacl::text,'body_md5',md5(p.prosrc),'definition_md5',md5(pg_get_functiondef(p.oid))) order by p.oid::regprocedure::text)
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in('retention_ai_source_ready','data_export_policy_binding','retention_execution_binding','closure_erasure_binding_v5','data_export_dataset_catalog','data_export_snapshot')) retention_routines;
rollback;

