begin read only;
set local statement_timeout = '5s';
select clock_timestamp() as observed_at,
  (select count(*) from supabase_migrations.schema_migrations) as migration_count,
  (select jsonb_agg(x order by x.version desc) from (select version,name from supabase_migrations.schema_migrations order by version desc limit 10) x) as latest_migrations,
  to_regclass('private.capacity4_transaction_probe')::text as probe_table,
  to_regprocedure('private.capacity4_transaction_probe_v1()')::text as probe_procedure,
  to_regprocedure('private.dispatch_one_job_v1(timestamptz,uuid[])')::text as dispatch_one_job,
  to_regprocedure('private.requeue_one_changed_worker_profile_v1(timestamptz)')::text as requeue_one_profile,
  to_regprocedure('private.marketplace_tick_transactions_v1(integer,timestamptz,jsonb)')::text as marketplace_transactions,
  (select count(*) from cron.job) as cron_jobs,
  (select jsonb_agg(jsonb_build_object('jobid',jobid,'name',jobname,'schedule',schedule,'active',active,'command',case when jobname='uskoci_marketplace_tick' then command else null end)) from cron.job) as cron;
rollback;

begin read only;
set local statement_timeout='5s';
with legal as (select public.rpc_get_legal_bundle() v)
select clock_timestamp() observed_at,
 (select v->'ready' from legal) legal_ready,
 (select v->>'reason' from legal) legal_reason,
 (select count(*) from private.legal_document_versions) legal_document_history,
 (select count(*) from private.legal_document_versions where is_active and retired_at is null and published_at<=statement_timestamp() and effective_at<=statement_timestamp()) legal_documents_active,
 (select count(*) from private.processor_map_sets where retired_at is null and effective_at<=statement_timestamp()) processor_maps_active,
 private.retention_ai_source_ready() retention_ai_source_ready,
 private.data_export_policy_binding() is null export_binding_null,
 private.retention_execution_binding() is null retention_binding_null,
 private.closure_erasure_binding_v5() is null closure_binding_null,
 (select count(*) from private.retention_policy_sets) retention_policy_sets,
 (select count(*) from private.retention_policy_rules) retention_policy_rules,
 (select count(*) from auth.users) auth_accounts,
 (select count(*) from public.app_accounts) app_accounts,
 (select count(*) from public.needs) needs,
 (select count(*) from public.agreements) agreements,
 (select count(*) from private.dispatch_schedule) scheduled_dispatch_jobs,
 (select count(*) from pg_stat_activity where datname=current_database()) connections,
 (select count(*) from pg_stat_activity where datname=current_database() and wait_event_type='Lock') lock_waits,
 (select count(*) from pg_stat_activity where datname=current_database() and state='idle in transaction') idle_in_transaction;
rollback;

begin read only;
set local statement_timeout='5s';
select clock_timestamp() observed_at, p.oid::regprocedure::text routine, p.prokind, p.prosecdef,
 pg_get_userbyid(p.proowner) owner,p.proconfig,p.proacl::text acl,
 md5(p.prosrc) body_md5,md5(pg_get_functiondef(p.oid)) definition_md5,
 case when p.proname='enqueue_on_need_change' then p.prosrc ~ 'private[.]dispatch_next_wave[[:space:]]*\(' end publication_calls_wave,
 case when p.proname='enqueue_on_need_change' then position('private.enqueue_dispatch' in p.prosrc)>0 end publication_enqueues
from pg_proc p join pg_namespace n on n.oid=p.pronamespace
where n.nspname='private' and p.proname in('dispatch_one_job_v1','requeue_one_changed_worker_profile_v1','marketplace_tick_transactions_v1','enqueue_on_need_change','wake_push_worker','marketplace_tick','dispatch_tick','capacity4_transaction_probe_v1')
order by routine;
rollback;

begin read only;
set local statement_timeout='5s';
select clock_timestamp() observed_at,
 (select count(*) from supabase_migrations.schema_migrations where name like '%transaction_probe_cleanup%') probe_cleanup_migrations,
 (select count(*) from private.capacity4_transaction_probe) probe_synthetic_rows,
 (select count(*) from cron.job where jobname='uskoci_dispatch_call_probe_20261108') probe_cron_jobs,
 (select jsonb_build_object('rls',relrowsecurity,'acl',relacl::text,'owner',pg_get_userbyid(relowner),'comment',obj_description(oid,'pg_class')) from pg_class where oid='private.capacity4_transaction_probe'::regclass) probe_table_metadata;
rollback;
